import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.DWKxYYJ1.js";import"./chunks/assets.tD9y118P.js";var i=JSON.parse(`{"title":"シナリオ / 作成","description":"AIベースのテスト自動化でQA時間を80%削減します。コードなしのテスト作成、自然言語によるシナリオ作成、多様なプラットフォームのサポートにより、QAの新しい基準を提示します。","frontmatter":{"title":"シナリオ / 作成","description":"AIベースのテスト自動化でQA時間を80%削減します。コードなしのテスト作成、自然言語によるシナリオ作成、多様なプラットフォームのサポートにより、QAの新しい基準を提示します。","head":[["meta",{"name":"keywords","content":"テスト自動化, テスティング生成型AI, Playwright, Selenium, リアルタイム品質フィードバック, 無停止テスト, AIベーステスト自動化, 継続的テスト(Continuous Testing), QAOps, TestOps, コードレス(Codeless), ローコード(Low-Code), 自己修復テスト(Self-healing), AIテスト自動化, コードレス自動化, QA自動化, ソフトウェアテスト, テストシナリオ生成, コードレステスト, 自然言語テスト, テスト自動化ツール, テスト自動化プラットフォーム, テスト効率化, Playwright, Selenium, QAOps, TestOps, シフトレフト(Shift-Left)テスト, シフトライト(Shift-Right)テスト"}],["meta",{"property":"og:title","content":"AIテスト自動化 | SyncETA"}],["meta",{"property":"og:description","content":"AIベースのテスト自動化でQA時間を80%削減します。コードなしのテスト作成、自然言語によるシナリオ作成、多様なプラットフォームのサポートにより、QAの新しい基準を提示します。"}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/synceta/"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/ja/synceta/scenario-create.html"}]],"sort":500},"headers":[],"relativePath":"ja/synceta/scenario-create.md","filePath":"ja/synceta/scenario-create.md","lastUpdated":1784591695000}`),a={name:`ja/synceta/scenario-create.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="シナリオ" tabindex="-1">シナリオ <a class="header-anchor" href="#シナリオ" aria-label="Permalink to “シナリオ”">​</a></h1><p>SyncETAを使用して、複雑なテストコードを作成することなく、実際のUIを通じてテストケースを作成し管理できます。</p><h2 id="シナリオとは" tabindex="-1">シナリオとは <a class="header-anchor" href="#シナリオとは" aria-label="Permalink to “シナリオとは”">​</a></h2><h4 id="「シナリオ」-とは以下のような機能テストの単位を意味します。" tabindex="-1"><strong><em>「シナリオ」</em></strong> とは以下のような機能テストの単位を意味します。 <a class="header-anchor" href="#「シナリオ」-とは以下のような機能テストの単位を意味します。" aria-label="Permalink to “「シナリオ」 とは以下のような機能テストの単位を意味します。”">​</a></h4><h5 id="「empasy」-のホームページにアクセスして問い合わせを送信" tabindex="-1">[ <strong><em>「empasy」</em></strong> のホームページにアクセスして問い合わせを送信 ] <a class="header-anchor" href="#「empasy」-のホームページにアクセスして問い合わせを送信" aria-label="Permalink to “[ 「empasy」 のホームページにアクセスして問い合わせを送信 ]”">​</a></h5><ol><li><strong><em>「empasy」</em></strong> のホームページにアクセス。</li><li><strong><em>「お問い合わせ」</em></strong> をクリック。</li><li>問い合わせ内容を入力。</li><li>問い合わせを送信。</li><li>正常な送信を確認。</li></ol><h2 id="シナリオ作成" tabindex="-1">シナリオ作成 <a class="header-anchor" href="#シナリオ作成" aria-label="Permalink to “シナリオ作成”">​</a></h2><h4 id="_1-シナリオメニューへ移動" tabindex="-1">1. シナリオメニューへ移動 <a class="header-anchor" href="#_1-シナリオメニューへ移動" aria-label="Permalink to “1. シナリオメニューへ移動”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><ol><li>左側のサイドバーの <strong><em>「シナリオ」</em></strong> メニューをクリック</li><li>右上の <strong><em>「新しいシナリオ」</em></strong> をクリック</li><li>シナリオ録画に必要な設定モーダルが表示されます。</li></ol></div><p><img src="/docs/assets/new_scenario.CxnBoB7X.png" alt="シナリオ作成のクリック" loading="lazy"></p><h4 id="_2-録画ブラウザの設定" tabindex="-1">2. 録画ブラウザの設定 <a class="header-anchor" href="#_2-録画ブラウザの設定" aria-label="Permalink to “2. 録画ブラウザの設定”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><ol><li>シナリオを作成するウェブページのURLを入力します。</li><li>録画を行うブラウザを選択します。</li></ol><ul><li>録画時はChrome -&gt; 実行時はEdgeを選択可能 (クロスブラウジングテスト)</li></ul><ol start="3"><li>録画を行うブラウザのサイズを設定します。</li></ol><ul><li>録画時は1400 x 800 -&gt; 実行時は800 x 600が可能 (レスポンシブテスト)</li></ul></div><p><img src="/docs/assets/select_option.BO9WUS-y.png" alt="シナリオ録画前の設定" loading="lazy"></p><h4 id="_3-収集イベントの設定" tabindex="-1">3. 収集イベントの設定 <a class="header-anchor" href="#_3-収集イベントの設定" aria-label="Permalink to “3. 収集イベントの設定”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><ul><li>収集するイベントタイプを選択した後、モーダル右下の録画開始ボタンを押してください。<br> 基本設定で録画を進めることを推奨します。</li></ul></div><p><img src="/docs/assets/allow_event.BTzP3-1K.png" alt="許可イベントの設定" loading="lazy"></p><h4 id="_4-録画開始" tabindex="-1">4. 録画開始 <a class="header-anchor" href="#_4-録画開始" aria-label="Permalink to “4. 録画開始”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>録画を開始するとブラウザが画面に表示されます。<br> 該当のブラウザで実際のテストを進めてください。<br> EX) Naverで <strong><em>「周辺の美味しい店」</em></strong> を検索</p><p>写真のようにレコードが収集されたことを確認できます。</p><ol><li>URLへ移動</li><li>検索バーをクリック</li><li>検索ワード(<strong><em>「周辺の美味しい店」</em></strong>)を入力</li><li>検索ボタンをクリック</li></ol></div><p><img src="/docs/assets/start_recording.C0eDEaiH.png" alt="録画開始" loading="lazy"></p><h4 id="_4-dom情報の収集" tabindex="-1">4. DOM情報の収集 <a class="header-anchor" href="#_4-dom情報の収集" aria-label="Permalink to “4. DOM情報の収集”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><ul><li>すべてのレコードはイベントが発生したDOMの情報を持っています。<br> EX) 検索ワード(<strong><em>「周辺の美味しい店」</em></strong>)を入力したinput要素の属性を収集</li></ul></div><p><img src="/docs/assets/select_dom_info.Dv7Rqw5o.png" alt="DOM情報の選択" loading="lazy"></p><h4 id="_5-録画中に新しいタブが開いた場合" tabindex="-1">5. 録画中に新しいタブが開いた場合 <a class="header-anchor" href="#_5-録画中に新しいタブが開いた場合" aria-label="Permalink to “5. 録画中に新しいタブが開いた場合”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>ブラウザで追加されたすべてのタブで、同様にシナリオの録画を続けることができます。</p></div><p><img src="/docs/assets/new_tap.JQeqWugH.png" alt="新しいタブ" loading="lazy"></p><h2 id="待機レコード" tabindex="-1">待機レコード <a class="header-anchor" href="#待機レコード" aria-label="Permalink to “待機レコード”">​</a></h2><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>レコードの実行間に、特定の条件を満たすまで待機時間を付与する機能です。</p><p>待機レコードの種類3つ</p><ol><li>時間待機 - 設定した時間だけ待機します。</li><li>要素露出待機 - 画面に特定の要素が表示されるまで待機します。</li><li>要素値一致待機 - 画面に特定の値が露出するまで待機します。</li></ol></div><h4 id="_1-時間待機条件の追加" tabindex="-1">1. 時間待機条件の追加 <a class="header-anchor" href="#_1-時間待機条件の追加" aria-label="Permalink to “1. 時間待機条件の追加”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>レコード実行前に待機時間を付与します。</p><ol><li>待機が必要なレコードを右クリックします。</li><li>待機条件追加をクリックした後、待機時間を設定します。(1000 = 1秒)</li></ol></div><p>レコードを右クリック <img src="/docs/assets/time_wait.Ck2J4xsR.png" alt="時間待機" loading="lazy"> 待機時間の設定 <img src="/docs/assets/time_wait2.BN7q3QL7.png" alt="待機時間設定" loading="lazy"> 待機レコードの作成 <img src="/docs/assets/time_wait3.Di0WXHU3.png" alt="待機レコード作成" loading="lazy"></p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>EX) URL移動後、画面の読み込み(ネットワーク状況を考慮して約3秒)時間待機した後、検索バーをクリックするように時間待機条件を追加</p></div><h4 id="_2-要素露出待機条件の追加" tabindex="-1">2. 要素露出待機条件の追加 <a class="header-anchor" href="#_2-要素露出待機条件の追加" aria-label="Permalink to “2. 要素露出待機条件の追加”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>特定の要素が画面に露出するまで待機します。</p><ol><li>待機が必要なレコードを右クリックします。</li><li>待機条件追加をクリックした後、要素露出待機を選択します。</li></ol></div><p>レコードを右クリック <img src="/docs/assets/dom_wait.DhHz2jZ9.png" alt="DOM待機" loading="lazy"> 録画中の画面で要素選択をクリックした後、<br> 録画が進行中のブラウザで待機する要素を選択します。 <img src="/docs/assets/dom_wait2.C30_95jZ.png" alt="DOM選択" loading="lazy"> 要素露出待機レコードの作成 <img src="/docs/assets/dom_wait3.CBtQ6C0E.png" alt="DOM待機レコード作成" loading="lazy"></p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>EX) 検索バーをクリックする前に、実際に画面に検索バー(input)が読み込まれるまで待機</p></div><h4 id="_3-要素値一致待機条件の追加" tabindex="-1">3. 要素値一致待機条件の追加 <a class="header-anchor" href="#_3-要素値一致待機条件の追加" aria-label="Permalink to “3. 要素値一致待機条件の追加”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>特定の要素に設定した値が露出するまで待機します。</p></div><p>レコードを右クリック <img src="/docs/assets/value_wait.97BmEy8x.png" alt="値待機" loading="lazy"> 録画中の画面で要素選択をクリックした後、<br> 録画が進行中のブラウザで待機する要素を選択します。 <img src="/docs/assets/value_wait2.W3u2wB2D.png" alt="値選択" loading="lazy"></p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>EX) ニュースのカルーセルに <strong><em>「韓国経済ビジネス」</em></strong> が露出するまで待機します</p></div><h2 id="検証レコード" tabindex="-1">検証レコード <a class="header-anchor" href="#検証レコード" aria-label="Permalink to “検証レコード”">​</a></h2><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>レコードの実行間に、特定の要素が露出するか、特定の値が露出するかを検証する機能です。</p><ol><li>特定の要素が画面に露出しているかを検証<br> EX) 美味しい店の検索後、画面に <strong><em>「美味しい店マップ」</em></strong> が露出しているかを確認</li><li>特定の値が画面に露出しているかを検証<br> EX) <strong><em>「プレイス」</em></strong> の最上段に <strong><em>「OOレストラン」</em></strong> が露出するかを確認</li></ol></div><h4 id="_1-要素露出検証レコードの追加" tabindex="-1">1. 要素露出検証レコードの追加 <a class="header-anchor" href="#_1-要素露出検証レコードの追加" aria-label="Permalink to “1. 要素露出検証レコードの追加”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>特定の要素が画面に露出しているかを検証します。</p></div><p>レコードを右クリック <img src="/docs/assets/valid_dom.2uHkx6Bq.png" alt="DOM検証" loading="lazy"> 録画中の画面で要素選択をクリックした後、<br> 録画が進行中のブラウザで検証する要素を選択します。 <img src="/docs/assets/valid_dom2.DSYmGpNO.png" alt="DOM検証選択" loading="lazy"> 検証レコードの作成 <img src="/docs/assets/valid_dom3.D3yXzcTH.png" alt="DOM検証レコード作成" loading="lazy"></p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>EX) Naverで <strong><em>「周辺の美味しい店」</em></strong> を検索後、<strong><em>「プレイス」</em></strong> が露出するかを検証します。</p></div><h4 id="_2-要素値検証レコードの追加" tabindex="-1">2. 要素値検証レコードの追加 <a class="header-anchor" href="#_2-要素値検証レコードの追加" aria-label="Permalink to “2. 要素値検証レコードの追加”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>特定の値が画面に露出しているかを検証します。</p></div><p>レコードを右クリック <img src="/docs/assets/valid_value.CTFJE1s6.png" alt="値検証" loading="lazy"> 録画中の画面で要素選択をクリックした後、<br> 録画が進行中のブラウザで検証する要素を選択します。<br> EX) プレイスの最上段に <strong><em>「ディアリスト延南」</em></strong> が露出するかを検証 <img src="/docs/assets/valid_value2.BB6NnGlc.png" alt="値検証選択" loading="lazy"> 検証レコードの作成 <img src="/docs/assets/valid_value3.PHN3oOuY.png" alt="値検証レコード作成" loading="lazy"></p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>EX) <strong><em>「プレイス」</em></strong> の最上段に <strong><em>「ディアリスト延南」</em></strong>が露出するかを確認</p></div><h4 id="_3-aiによる画面検証" tabindex="-1">3. AIによる画面検証 <a class="header-anchor" href="#_3-aiによる画面検証" aria-label="Permalink to “3. AIによる画面検証”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>画面内の特定の値や要素の露出ではなく、画像ベースの検証が必要な場合に使用します。</p></div><p>レコードを右クリック <img src="/docs/assets/valid_ai.BLlZ6YWJ.png" alt="AI検証" loading="lazy"> AIプロンプトを選択した後、プロンプトを入力します。<br> 現在のブラウザの画面をSync-ETAエージェントが自動的にキャプチャし、AIで検証します。</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>AWS Bedrock - claude-3-haikuモデルを使用中</p></div><p><img src="/docs/assets/valid_ai2.BNZ_hmqg.png" alt="AIプロンプト入力" loading="lazy"></p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>EX) <strong><em>「周辺の美味しい店」</em></strong> を検索後、画面に <strong><em>「マップ」</em></strong> が正常に露出するかを確認</p></div><h2 id="シナリオの修正" tabindex="-1">シナリオの修正 <a class="header-anchor" href="#シナリオの修正" aria-label="Permalink to “シナリオの修正”">​</a></h2><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>既存のシナリオの特定の部分から続けて録画を進める機能です。</p></div><h4 id="_1-修正するシナリオの選択" tabindex="-1">1. 修正するシナリオの選択 <a class="header-anchor" href="#_1-修正するシナリオの選択" aria-label="Permalink to “1. 修正するシナリオの選択”">​</a></h4><p>シナリオ修正をクリック <img src="/docs/assets/edit.DharqlJd.png" alt="シナリオ修正" loading="lazy"> 続けて録画するレコードを選択します。 <img src="/docs/assets/edit2.Ck35xb_N.png" alt="修正レコード選択" loading="lazy"></p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><ol><li>シナリオ作成と同様に録画ブラウザが表示されます。</li><li>続けて録画を希望するレコードまでスクリプトが実行されます。</li><li>設定したレコードに到達すると、その時点からブラウザで発生するイベントを収集します。</li></ol></div><p><img src="/docs/assets/edit3.CiNnpFll.png" alt="修正スクリプト実行" loading="lazy"></p><h2 id="付加機能" tabindex="-1">付加機能 <a class="header-anchor" href="#付加機能" aria-label="Permalink to “付加機能”">​</a></h2><h4 id="_1-ノート機能" tabindex="-1">1. ノート機能 <a class="header-anchor" href="#_1-ノート機能" aria-label="Permalink to “1. ノート機能”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>レコードの内容を入力します。</p></div><p><img src="/docs/assets/comment.bH8IGTY6.png" alt="コメント入力" loading="lazy"></p><h4 id="_2-失敗復旧スクリプト" tabindex="-1">2. 失敗復旧スクリプト <a class="header-anchor" href="#_2-失敗復旧スクリプト" aria-label="Permalink to “2. 失敗復旧スクリプト”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>レコードが失敗した場合に復旧スクリプトが実行されます。</p></div><p><img src="/docs/assets/recover.BpaZA4Gc.png" alt="失敗復旧" loading="lazy"></p><h4 id="_3-データセット" tabindex="-1">3. データセット <a class="header-anchor" href="#_3-データセット" aria-label="Permalink to “3. データセット”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>入力値を指定します。<br> EX) 検索ワード(<strong><em>「周辺の美味しい店」</em></strong>)をユーザーが指定した値に置換します。<br> ** 詳細な説明は <strong><em>「データセット」</em></strong> を参照</p></div><p><img src="/docs/assets/dataset.BNYNMS0h.png" alt="データセット" loading="lazy"></p><h4 id="_4-削除" tabindex="-1">4. 削除 <a class="header-anchor" href="#_4-削除" aria-label="Permalink to “4. 削除”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>収集したレコードを削除します。<br> EX) 録画中に間違った部分をクリックした場合、該当のレコードを削除します。</p></div><p><img src="/docs/assets/delete.BiOSPnzX.png" alt="レコード削除" loading="lazy"></p><h4 id="_5-無効化" tabindex="-1">5. 無効化 <a class="header-anchor" href="#_5-無効化" aria-label="Permalink to “5. 無効化”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>収集した情報を削除せずに、実行時に除外します。</p></div><p><img src="/docs/assets/disable.BWI2I4rp.png" alt="レコード無効化" loading="lazy"></p>`,77)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};